import {Shift,TYPES,ORDER,lifeStep,threatCells} from './engine.mjs';
const $=s=>document.querySelector(s);let shift=new Shift(),filter=null,selectedId=null,last=performance.now(),lifeGen=-1,stampUntil=0,reported=false,guideResume=false;const width=38,height=18,boards={};let boardTick=0;
function initBoards(){for(const[type,t]of Object.entries(TYPES)){const seed=new Set();for(let y=1;y<height-1;y++)for(let x=1;x<width-1;x++)if(((x*17+y*31+x*y*3+ORDER.indexOf(type)*11)%19)<4)seed.add(y*width+x);boards[type]={life:seed};}lifeGen=-1;}
$('#zones').innerHTML=ORDER.map((type,i)=>`<article class="zone" id="zone-${type}"><button class="zonepick" data-select="${type}" aria-label="${TYPES[type].name}の伝票を調べる"><span><b>0${i+1} / ${TYPES[type].name}</b><small>${TYPES[type].pattern}</small></span><span class="zonestatus" id="status-${type}">パターン見本</span></button><canvas class="cellview" id="canvas-${type}" width="760" height="360" role="img" aria-label="${TYPES[type].label}：${TYPES[type].hint}"></canvas><div class="zonefoot"><p id="hint-${type}">${TYPES[type].hint}</p><button class="patch" data-patch="${type}" disabled>▥ 根本修正 · 10秒</button></div></article>`).join('');
for(const type of ORDER){const canvas=$('#canvas-'+type);boards[type]={};canvas.onclick=()=>selectZone(type);}initBoards();
function selectZone(type){filter=type;selectedId=null;stampUntil=0;renderUI(true);if(matchMedia('(max-width:720px)').matches)setView('desk');}
function setView(view){document.body.dataset.view=view;$('#showBoard').setAttribute('aria-pressed',String(view==='board'));$('#showDesk').setAttribute('aria-pressed',String(view==='desk'));}
function getRequest(){return shift.pending(filter).find(r=>r.id===selectedId)||null;}
function renderPaper(r){const t=TYPES[r.type],labels=r.type==='auth'?['本人','鍵の送信先']:r.type==='share'?['持ち主','閲覧者']:r.type==='flood'?['送信者','毎秒の件数']:['資料の種類','送り先'];$('#paper').innerHTML=`<div class="paperhead"><span>通信審査局 / TRANSIT FORM</span><span>#${String(r.id).padStart(3,'0')}</span></div><h3>${r.type==='exfil'?'送信申請書':r.type==='flood'?'受付申請書':r.type==='share'?'閲覧申請書':'再設定申請書'}</h3><p class="papertype">${t.name} · ${r.type==='exfil'?'OUTBOUND / 外へ出る通信':'INBOUND / 内へ入る通信'}</p><div class="paperrow"><span>${labels[0]}</span><strong class="${r.type==='exfil'?'jp':''}">${r.a}</strong></div><div class="paperrow"><span>${labels[1]}</span><strong class="${r.type==='exfil'?'jp':''}">${r.b}${r.type==='flood'?' 件':''}</strong></div><div class="rule"><b>通過条件</b><br>${t.rule}</div><div class="deadline"><span>AUTO PASS IN</span><b id="deadline">${Math.max(0,Math.ceil(r.deadline-shift.time))}s</b></div>`;$('#paper').hidden=false;$('#empty').hidden=true;}
function renderUI(force=false){const pending=shift.pending(filter);if(!pending.some(r=>r.id===selectedId)){selectedId=pending[0]?.id??null;force=true;}const r=getRequest();$('#clock').textContent=format(120-shift.time);$('#eventTime').textContent=format(shift.time);$('#integrity').textContent=shift.data;$('#trust').textContent=shift.trust;$('#dataMeter').style.width=shift.data+'%';$('#trustMeter').style.width=shift.trust+'%';$('#pending').textContent=String(shift.pending().length).padStart(2,'0');$('#mobileCount').textContent=shift.pending().length;$('#fixed').textContent=shift.repaired;$('#deskCount').textContent=String(pending.length).padStart(2,'0')+' WAITING';$('#filterLabel').textContent=filter?TYPES[filter].name+' の伝票':'すべての領域';$('#eventLog').textContent=shift.lastLog;$('#startBtn').hidden=shift.started;$('#pauseBtn').hidden=!shift.started;$('#pauseBtn').disabled=shift.done;$('#pauseBtn').textContent=shift.running?'一時停止 Ⅱ':'再開 ▶';const busy=ORDER.find(k=>shift.zones[k].repairEnd);$('#worker').textContent=busy?TYPES[busy].name+'：あと'+Math.ceil(shift.zones[busy].repairEnd-shift.time)+'秒':'修正担当：待機中';
const q=pending.map(x=>`<button class="queueitem ${x.id===selectedId?'selected':''} ${x.deadline-shift.time<5?'urgent':''}" data-ticket="${x.id}" aria-label="伝票 ${x.id} ${TYPES[x.type].name}">#${String(x.id).padStart(3,'0')}</button>`).join('');if($('#queue').innerHTML!==q)$('#queue').innerHTML=q;
if(r){if(force||$('#paper').dataset.ticket!==String(r.id)){renderPaper(r);$('#paper').dataset.ticket=r.id;}if($('#deadline'))$('#deadline').textContent=Math.max(0,Math.ceil(r.deadline-shift.time))+'s';}else{$('#paper').hidden=true;$('#paper').dataset.ticket='';$('#empty').hidden=false;$('#empty').innerHTML=shift.started?'<div>▤</div><h3>この領域の伝票は、審査済み。</h3><p>次の通信を待つか、<br>「全伝票を表示」で別の領域へ。</p><span>静かな間に根本修正もできます。</span>':'<div>▤</div><h3>最初の伝票を、待っている。</h3><p>当直を開始すると通信が届きます。<br>二つの欄を照合して、通すか止めるか。</p><span>判定はすぐ、左の盤面へ返ります。</span>';}
$('#allowBtn').disabled=$('#denyBtn').disabled=!shift.running||!r||performance.now()<stampUntil;
for(const type of ORDER){const z=shift.zones[type],n=shift.pending(type).length;$('#zone-'+type).classList.toggle('selected',filter===type||(!filter&&r?.type===type));$('#zone-'+type).classList.toggle('underattack',z.attacks>0);$('#zone-'+type).classList.toggle('fixed',z.fixed);$('#status-'+type).textContent=!shift.started?'パターン見本':z.fixed?'▥ 防壁稼働':z.repairEnd?'修正中 '+Math.ceil(z.repairEnd-shift.time)+'s':z.attacks?'侵入 '+z.attacks+'件':n?'審査待ち '+n+'件':'● 正常';$('#hint-'+type).textContent=z.fixed?'青い防壁が再侵入を防ぐ。':z.attacks?TYPES[type].label+'が進行中。修正で止める。':TYPES[type].hint;const p=$('[data-patch="'+type+'"]');p.disabled=!shift.running||z.fixed||!!busy;p.textContent=z.fixed?'▥ 修正済み':z.repairEnd?'修正中… '+Math.ceil(z.repairEnd-shift.time)+'s':'▥ 根本修正 · 10秒';}
if(shift.done&&!reported){reported=true;showReport();}}
function format(t){const s=Math.max(0,Math.ceil(t));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
function decide(allow){if(performance.now()<stampUntil)return;const r=getRequest();if(!r||!shift.decide(r.id,allow))return;$('#stamp').textContent=allow?'APPROVED':'DENIED';$('#stamp').className='stamp show '+(allow?'approved':'denied');stampUntil=performance.now()+650;selectedId=null;renderUI(true);}
function drawCell(ctx,x,y,color,outline=false){if(x<0||x>=width||y<0||y>=height)return;ctx.fillStyle=color;if(outline){ctx.strokeStyle=color;ctx.setLineDash([3,3]);ctx.strokeRect(x*20+3,y*20+3,14,14);ctx.setLineDash([]);}else ctx.fillRect(x*20+3,y*20+3,14,14);}
function drawBoards(now){const visualTime=shift.started?shift.time:now/1000;const gen=Math.floor(visualTime*3);if(gen!==lifeGen){for(const type of ORDER){boards[type].life=lifeStep(boards[type].life,width,height);if(gen%12===0){const x=3+(gen+ORDER.indexOf(type)*7)%26;for(const[dx,dy]of[[1,0],[2,1],[0,2],[1,2],[2,2]])boards[type].life.add((3+dy)*width+x+dx);}}lifeGen=gen;}$('#generation').textContent='GEN '+String(gen).padStart(4,'0');for(const type of ORDER){const ctx=$('#canvas-'+type).getContext('2d'),z=shift.zones[type];ctx.fillStyle='#10191d';ctx.fillRect(0,0,760,360);for(let y=0;y<height;y++)for(let x=0;x<width;x++)drawCell(ctx,x,y,'#1b2a30');for(const n of boards[type].life)drawCell(ctx,n%width,Math.floor(n/width),'#487456');
// Service pathways make direction readable even when the automaton settles.
for(let x=1;x<37;x++){drawCell(ctx,x,9,'#284c3b');if((x+gen)%12<2)drawCell(ctx,x,9,'#a9cfa0');}for(let y=6;y<=12;y++)for(let x=31;x<=35;x++)if((x+y)%3)drawCell(ctx,x,y,'#527a52');
if(!shift.started){for(const[x,y]of threatCells(type,visualTime%12,ORDER.indexOf(type)))drawCell(ctx,x,y,'#b95d55');}else{for(const r of shift.pending(type)){const age=shift.time-r.at;for(const[x,y]of threatCells(type,Math.min(age*.3,3),r.id).slice(0,14))drawCell(ctx,x,y,'#dfb975',true);}
const attacks=shift.requests.filter(r=>r.type===type&&!r.valid&&['allow','timeout'].includes(r.status));for(const r of attacks){const age=shift.time-(r.decisionAt??r.at),pixels=threatCells(type,age,r.id);for(const[x,y]of pixels){if(!z.fixed)drawCell(ctx,x,y,'#e67b68');else if(type==='exfil'?x>=20:x<=16)drawCell(ctx,x,y,'#ce7767');}}
for(const e of shift.effects.filter(e=>e.type===type)){const age=shift.time-e.at;if(age>6)continue;if(e.kind==='good'){for(let k=0;k<5;k++)drawCell(ctx,(Math.floor(age*6)+k+2)%36,9,'#d2efbd');}if(e.kind==='stop'||e.kind==='falseblock'){for(let k=0;k<4;k++)drawCell(ctx,3+k,8+(k%2),e.kind==='stop'?'#87c6df':'#d5a16c');}}
}
if(z.fixed){for(let y=2;y<16;y++){drawCell(ctx,18,y,'#8fc8e8');drawCell(ctx,19,y,'#426e8b');}for(let y=5;y<13;y+=3)drawCell(ctx,type==='exfil'?20:17,y,'#f1bd93');}else if(z.repairEnd){const progress=1-(z.repairEnd-shift.time)/10;for(let y=2;y<2+Math.floor(progress*14);y++)drawCell(ctx,18,y,'#85b9d4',true);}
ctx.font='16px monospace';ctx.fillStyle='#8ea79f';ctx.fillText(type==='exfil'?'← OUTBOUND':'INBOUND →',16,342);ctx.textAlign='right';ctx.fillStyle=z.fixed?'#a7d7f2':'#88a092';ctx.fillText(z.fixed?'BARRIER ACTIVE':!shift.started?'PATTERN PREVIEW':z.attacks?'THREAT INSIDE':'MONITORING',744,342);ctx.textAlign='left';}}
function showReport(){$('#reportTitle').textContent=shift.data>=85&&shift.trust>=85?'守ったのは、データと信頼。':shift.data>=60?'当直終了。次は、もっと守れる。':'赤い侵食が、抜け道を広げた。';$('#reportMetrics').innerHTML=`<div><strong>${shift.data}%</strong><small>守ったデータ</small></div><div><strong>${shift.trust}%</strong><small>利用者の信頼</small></div><div><strong>${shift.repaired}/4</strong><small>根本修正</small></div>`;$('#reportZones').innerHTML=ORDER.map(type=>{const z=shift.zones[type];return `<div class="reportzone"><b>${TYPES[type].name} / ${TYPES[type].label}　${z.fixed?'▥ 修正済み':'未修正'}</b><p>正しい審査 ${z.correct}件 · 不正通過 ${z.missed}件 · 防壁の自動拒否 ${z.defended}件</p><p>守る仕組み：${TYPES[type].patch}。</p></div>`;}).join('');$('#report').showModal();}
function reset(){shift=new Shift();selectedId=null;filter=null;reported=false;stampUntil=0;$('#stamp').className='stamp';$('#report').close();initBoards();setView('board');renderUI(true);}
$('#startBtn').onclick=()=>{shift.start();filter=null;last=performance.now();renderUI(true)};$('#pauseBtn').onclick=()=>{if(shift.done)return;shift.running=!shift.running;last=performance.now();renderUI()};$('#zones').onclick=e=>{const patch=e.target.closest('[data-patch]'),pick=e.target.closest('[data-select]');if(patch){shift.repair(patch.dataset.patch);renderUI();}else if(pick)selectZone(pick.dataset.select)};$('#queue').onclick=e=>{const b=e.target.closest('[data-ticket]');if(b){selectedId=Number(b.dataset.ticket);stampUntil=0;renderUI(true)}};$('#allBtn').onclick=()=>{filter=null;selectedId=null;renderUI(true)};$('#allowBtn').onclick=()=>decide(true);$('#denyBtn').onclick=()=>decide(false);$('#resetBtn').onclick=reset;$('#retryBtn').onclick=reset;$('#closeReport').onclick=()=>$('#report').close();$('#guideBtn').onclick=()=>{guideResume=shift.running;shift.running=false;$('#guide').showModal();renderUI()};function closeGuide(){$('#guide').close();if(guideResume&&!shift.done)shift.running=true;guideResume=false;last=performance.now();renderUI()}$('#closeGuide').onclick=closeGuide;$('#guideStart').onclick=closeGuide;$('#guide').addEventListener('cancel',e=>{e.preventDefault();closeGuide()});$('#showBoard').onclick=()=>setView('board');$('#showDesk').onclick=()=>setView('desk');document.addEventListener('keydown',e=>{if(e.repeat||$('#guide').open||$('#report').open||['INPUT','TEXTAREA','BUTTON'].includes(document.activeElement?.tagName))return;if(e.key==='ArrowLeft'){e.preventDefault();decide(false)}else if(e.key==='ArrowRight'){e.preventDefault();decide(true)}});
let uiTick=0;function frame(now){const dt=Math.min(.5,(now-last)/1000);last=now;if(shift.running)shift.advance(dt);if(now-uiTick>150){if(now>=stampUntil)$('#stamp').classList.remove('show');renderUI();drawBoards(now);uiTick=now;}requestAnimationFrame(frame);}renderUI(true);requestAnimationFrame(frame);
